"use strict";
/* Zoom join flow installer for the booking engine.
 * Replaces src/templates.js, src/emailhtml.js, src/engine.js with the
 * zoom-enabled versions (backups saved as .bak), sets the foglalas-okosan
 * meeting link + 5-minute join email in data/clients.json, restarts the
 * service and prints health. Run on the VPS:  node z.js
 */
const fs = require("fs"), path = require("path"), cp = require("child_process");
const APP = process.argv[2] || "/opt/foglalas-engine";
const FILES = {"src/templates.js": "", "src/emailhtml.js": "", "src/engine.js": ""};
try {
  for (const [rel, b64] of Object.entries(FILES)) {
    const p = path.join(APP, rel);
    if (!fs.existsSync(p)) { console.error("MISSING " + p + " (wrong directory?)"); process.exit(1); }
    fs.copyFileSync(p, p + ".bak");
    fs.writeFileSync(p, Buffer.from(b64, "base64"));
    console.log("updated " + rel);
  }
  const cf = path.join(APP, "data/clients.json");
  const c = JSON.parse(fs.readFileSync(cf, "utf8"));
  const fo = c["foglalas-okosan"];
  if (!fo) { console.error("foglalas-okosan client not found"); process.exit(1); }
  fo.booking.meeting_link = "https://us05web.zoom.us/j/5755339086?pwd=tJJaI5Os0wGGmO5hs1MTt28vNhBYpy.1";
  fo.booking.location_mode = "online";
  fo.email_meet_minutes_before = 5;
  fs.writeFileSync(cf + ".tmp", JSON.stringify(c, null, 2));
  fs.renameSync(cf + ".tmp", cf);
  console.log("config updated (zoom link + 5 min join email)");
  // syntax check before restarting
  for (const rel of Object.keys(FILES)) cp.execSync("node --check " + path.join(APP, rel));
  console.log("syntax ok");
  if (process.argv[3] !== "norestart") {
    cp.execSync("systemctl restart foglalas-engine");
    cp.execSync("sleep 3");
    const out = cp.execSync("curl -s http://localhost:3000/health").toString();
    console.log("health: " + out);
    console.log(out.includes('"ok":true') ? "ZOOM-DEPLOY-DONE" : "HEALTH-NOT-OK check journalctl -u foglalas-engine");
  } else { console.log("norestart mode done"); }
} catch (e) { console.error("FAILED: " + e.message); process.exit(1); }
